import type { TermInput } from "@/lib/schema";

/**
 * Laws around oncology (roadmap row 137): statutes, regulations, guidance and court rulings that decide how cancer
 * medicines are approved, paid for, tested, and how patients' data and genes are protected. Each record opens with
 * the jurisdiction, the instrument, the year and a link to the primary text. Modelled as glossary terms in the
 * "Regulation & policy" category; the /law/ page groups them by jurisdiction and theme through LAW_INDEX.
 * Chinese TL;DRs are exported as tldrZh for the i18n owner to merge into src/data/i18n/zh.ts.
 */
const asOf = "2026-09-17";
const W = (s: string) => `https://en.wikipedia.org/wiki/${s}`;
type T = Omit<TermInput, "kind" | "asOf" | "category">;
const t = (x: T): TermInput => ({
  kind: "term", asOf, category: "Regulation & policy",
  ...x,
  links: [...(x.wikipedia ? [{ label: "Wikipedia", url: x.wikipedia }] : []), ...(x.links ?? [])],
  tags: ["law", ...(x.tags ?? [])],
});

export type LawJurisdiction = "us" | "eu" | "uk" | "de" | "fr" | "jp" | "cn" | "in" | "intl";
export type LawTheme = "approval" | "paying" | "testing" | "data" | "prevention";
export type LawInstrument = "statute" | "regulation" | "guidance" | "court ruling" | "scheme" | "treaty" | "declaration";
export type LawIndexRow = { id: string; jurisdiction: LawJurisdiction; year: number; instrument: LawInstrument; themes: LawTheme[] };

export const LAW_JURISDICTIONS: Record<LawJurisdiction, string> = {
  us: "United States", eu: "European Union", uk: "United Kingdom", de: "Germany", fr: "France", jp: "Japan", cn: "China", in: "India", intl: "International",
};
